# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_today(settings):
    return datetime.datetime.now(bk_tz(settings)).date()


# ── bookkeeping kit: Xero ledger adapter (inlined into Xero nodes by gen-ext.js) ──
# Every write passes xero_tenant_id so it lands in the client's own Xero organisation
# (myhub-mcp-servers PR #558). Reads pass it too.
import base64
from collections import Counter

XERO = "xero-accounting"
XERO_EXPENSE_TYPES = {"EXPENSE", "DIRECTCOSTS", "OVERHEADS", "FIXED", "CURRENT", "INVENTORY", "PREPAYMENT", "NONCURRENT"}
XERO_REVENUE_TYPES = {"REVENUE", "SALES", "OTHERINCOME"}
XERO_DEAD = {"DELETED", "VOIDED"}


def xero_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    # Bound first on purpose: the platform's Publish lint only counts plain assignments as a function's own names,
    # so an `except ... as exc` name alone reads as undefined inside a helper.
    exc = None
    try:
        return api.connectors.invoke(server=XERO, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError(xero_error_text(exc)) from None


def xero_error_text(exc):
    """Xero's own validation messages (the useful part, at the end of a long error), else the error text."""
    text = str(exc)
    at = text.find("ValidationErrors")
    messages = []
    for m in re.findall(r'"Message"\s*:\s*"((?:[^"\\]|\\.)*)"', text[at:] if at >= 0 else ""):
        if m not in messages:
            messages.append(m)
    return ("Xero says: " + "; ".join(messages)) if messages else text[:600]


def xero_rows(result, key):
    if isinstance(result, dict):
        return result.get(key) or []
    if isinstance(result, list):
        return result
    return []


# ── Gather bills ──


def _xero_date(value):
    """Xero JSON dates arrive as '2026-10-01T00:00:00' (…String fields) or '/Date(1759276800000+0000)/'."""
    s = str(value or "")
    m = re.match(r"/Date\((\d+)", s)
    if m:
        return datetime.datetime.fromtimestamp(int(m.group(1)) / 1000, datetime.timezone.utc).date()
    try:
        return datetime.date.fromisoformat(s[:10])
    except ValueError:
        return None


problem = ""
settings = bk_read_json(BK_SETTINGS) or {}
today = bk_today(settings)
soon = today + datetime.timedelta(days=14)
open_items = [t for t in (api.workq.list(status="not_started") + api.workq.list(status="in_progress"))
              if "bookkeeping" in (t.get("labels") or [])]
clients = []
if not settings:
    problem = "Bookkeeping isn't set up yet."
for f in api.files.list(path=BK_CLIENTS) if settings else []:
    if f.get("kind") != "file" or not str(f.get("path", "")).endswith(".json"):
        continue
    client = bk_read_json(f["path"]) or {}
    if not client.get("xero_tenant_id"):
        continue
    row = {"name": client.get("name"), "slug": client.get("slug"), "error": "",
           "draft": [0, 0.0], "awaiting": [0, 0.0], "due_soon": [0, 0.0], "overdue": [0, 0.0],
           "in_review": 0, "exceptions": 0, "top_overdue": []}
    try:
        bills = []
        # One where clause per status: Xero silently returns nothing when `where` and `statuses` are
        # combined (myhub-mcp-servers #560).
        for status_name in ("DRAFT", "SUBMITTED", "AUTHORISED"):
            for page in range(1, 11):
                rows = xero_rows(xero_call("list_invoices", client["xero_tenant_id"],
                                           where='Type=="ACCPAY" AND Status=="' + status_name + '"', page=page), "Invoices")
                bills.extend(rows)
                if len(rows) < 100:
                    break
        for b in bills:
            due = _xero_date(b.get("DueDateString") or b.get("DueDate"))
            amount = bk_money(b.get("AmountDue")) or bk_money(b.get("Total")) or 0.0
            status = b.get("Status")
            if status == "DRAFT":
                bucket = "draft"
            elif status == "SUBMITTED":
                bucket = "awaiting"
            elif due and due < today:
                bucket = "overdue"
                row["top_overdue"].append({"supplier": (b.get("Contact") or {}).get("Name"),
                                           "number": b.get("InvoiceNumber"), "due": str(due), "amount": amount})
            elif due and due <= soon:
                bucket = "due_soon"
            else:
                continue
            row[bucket][0] += 1
            row[bucket][1] = round(row[bucket][1] + amount, 2)
        row["top_overdue"] = sorted(row["top_overdue"], key=lambda x: -x["amount"])[:5]
    except Exception as exc:
        row["error"] = str(exc)[:200]
    for t in open_items:
        labels = t.get("labels") or []
        if client.get("slug") in labels:
            if "bill-review" in labels:
                row["in_review"] += 1
            if "bill-exception" in labels:
                row["exceptions"] += 1
    clients.append(row)

summary = {"as_of": str(today), "due_by": str(soon), "clients": clients,
           "recipients": settings.get("digest_recipient_ids") or [x for x in [settings.get("reviewer_id")] if x]}
